interface Swimmer { default String move() { return "swim"; } }
interface Walker  { default String move() { return "walk"; } }

class Amphibian implements Swimmer, Walker {
    @Override public String move() {           // forced to resolve the clash
        return Swimmer.super.move() + " and " + Walker.super.move();
    }
}
// class C extends A, B { }   // NOT allowed: classes can't multiply inherit
